[
 {
  "name": "S1 sybil verification ring (size 10, minimum stake)",
  "cost_model": {
   "verifications_needed": "10 agents x 9 incoming each = 90 ring-internal verifications",
   "wall_clock": "each sybil must be >=24h old and have >=1 received verification before it may verify (verify.ts:200,206) -> the ring cannot bootstrap faster than 24h",
   "tasks": 0,
   "usdc_bond": 0.0,
   "why_zero_usdc": "free tasks and verifications need no wallet or bond (SKILL.md v1.3.9 \u00a73.4, \u00a75.1)",
   "total_usdc": 0.0
  },
  "reputation_gained": {
   "local": 0.0,
   "eigen_victim_000": 0.054,
   "blended_if_local_0": 0.038
  },
  "cost_per_point": 0.0,
  "detectability": "HIGH on inspectability, LOW on cost: 90 verifications between 10 IDs registered within 24h of each other, with no verifications from any of the 730 honest agents, is a one-query graph read.",
  "mitigation": "Weight verifications by the verifier's own degree centrality, or require a ring member to receive >=1 verification from outside its registration cohort.",
  "honest_agent_side_effects": "New honest agents register in cohorts too (framework release waves), so the cohort rule would delay honest onboarding by up to 24h and add one cross-cohort verification of work before the agent may verify."
 },
 {
  "name": "S2 self-dealing task farm (creator auto-accepts its own alt's deliveries)",
  "cost_model": {
   "tasks": 10,
   "usdc": 0.0,
   "why_zero_usdc": "a free task has no minimum, and an alt posting + auto-accepting its own delivery moves no money (SKILL.md v1.3.9 \u00a77.1, \u00a76)",
   "wall_clock_days": "auto-release is the 7-day timer (auto_release_at = delivery + 7d, SPEC \u00a7Auto-Accept) -> about 7 days for the first ten, then pipelined",
   "budget_effect": "auto-accepts earn NO budget (governance.ts:16, SKILL.md v1.3.9 \u00a75.1), so the farm cannot scale on budget; a fresh identity is capped at 10 concurrent claims",
   "bond": "0.0 \u2014 free tasks never need a bond (governance.ts:52, SKILL.md \u00a75.1)",
   "remap_note": "the task term is ADDITIVE and never renormalises the peer weights (calculator.ts:14)"
  },
  "reputation_gained": {
   "local_task_term_only": 0.1121,
   "local_full_if_no_verifications": 0.1621,
   "eigen": 0.0,
   "blended": 0.0336
  },
  "cost_per_point": 0.0,
  "detectability": "MEDIUM-HIGH: the delivering identity has zero verifications received and every one of its task acceptances is accepted_by='auto' (calculator.ts:122 records the 0.5 weight), which is visible in public task rows.",
  "mitigation": "Cap the task term for an agent whose accepted deliveries are 100% auto-accepted and whose verification count is 0 \u2014 the term is already separable, so the fix is one predicate.",
  "honest_agent_side_effects": "An honest, low-traffic agent whose first deliveries genuinely auto-accept (the buyer never reviews) would be capped too. Reaching alt accounts requires the fix to travel with the *payer/deliverer pair*, not the deliverer alone, so the residual evasion is a two-account alternation with a delayed accept."
 },
 {
  "name": "S3 timing exploitation of decay (stale positive records)",
  "cost_model": {
   "mechanism": "a verification 180 days old carries exp(-180/60)=0.0498 of its weight",
   "tasks": 0,
   "usdc": 0.0,
   "wall_clock": "180 days of holding an identity"
  },
  "reputation_gained": {
   "decay_factor_at_180d": 0.0498,
   "half_lives_elapsed": 2.08,
   "note": "180 d / 60 d constant = 3.0 time constants = 4.33 half-lives; the residual is 4.98%, not 12.5%"
  },
  "cost_per_point": null,
  "detectability": "LOW as an attack \u2014 this is the intended behaviour, not an exploit. The finding is that the halving unit is the 60-day constant, so a 6-month-old record is worth ~5%, and no attacker action is required.",
  "mitigation": "None needed for the attack; instead publish the half-life (41.6 d) in the docs, because the reviewer's own note shows readers conflating the 60-day constant with a half-life.",
  "honest_agent_side_effects": "None \u2014 no parameter change is proposed."
 },
 {
  "name": "S4 reputation parking (hold a high local score, stop working)",
  "cost_model": {
   "mechanism": "with no new verifications the local score stays raw*confidence at the last computed value; decays only through the age of the EXISTING rows",
   "tasks_held": 1,
   "usdc": 0.0,
   "wall_clock": "indefinite"
  },
  "reputation_gained": {
   "parking_retention_at_180d": 0.0498,
   "confidence_frozen_at": "min(1, log(1+n)/log(21)) for the n it stopped at"
  },
  "cost_per_point": null,
  "detectability": "LOW: a parked identity is indistinguishable from a dormant honest agent in the public data. Only the absence of new work distinguishes them, and absence is not evidence.",
  "mitigation": "Add a recency term to the pre-trust vector so unpinned agents lose eigen weight if they have no activity in 2 x DECAY_DAYS; alternatively expose last_active and let buyers filter.",
  "honest_agent_side_effects": "Seasonal agents (quarterly batch work) would lose eigen weight and need one verification to recover it, which costs them a peer's attention."
 },
 {
  "name": "S5 dilution against others (fail, timeout and low-coherence reports on a rival)",
  "cost_model": {
   "verifications_needed": "each report costs one assigned verification; verify.ts requires an assignment issued to the verifier for that exact target (verify.ts:166,169) and marks it used (verify.ts:174), so a verifier cannot repeat-report one target without being reassigned",
   "tasks": 0,
   "usdc": 0.0,
   "suspension": "if a verifier's last 5 verifications are all timeouts, updateAgentStatus suspends it (status active -> suspended after 5 consecutive timeouts)",
   "coherence_penalty": "a low coherence_score does not merely fail to help: signal = 0.5+0.5*coh for a pass, and 0 for a timeout, so a timeout also lowers the target's uptime component"
  },
  "reputation_gained": {
   "attacker_gain": 0.0,
   "victim_uptime_loss_per_timeout": 1.0,
   "attacker_own_contribution_bonus": 0.2794
  },
  "cost_per_point": null,
  "detectability": "HIGH after 5 reports: the 5-consecutive-timeout suspension is mechanical and public. Before that, a verifier whose timeouts are all aimed at one target is visible in the verification rows.",
  "mitigation": "Make the suspension counter target-scoped as well as global (5 timeouts against one target suspends reporting on that target).",
  "honest_agent_side_effects": "A verifier working a genuinely broken agent would be cut off from that target after 5 honest timeouts; the human-review path would need to exist."
 },
 {
  "name": "S6 bonded bounty claim farming (sybil economics recovery)",
  "cost_model": {
   "usdc_bond": 1.0,
   "slots": 1,
   "slash_on_expiry": 1.0,
   "slash_on_dispute": 1.0,
   "tasks": 3,
   "wall_clock_days": 7,
   "budget": "base 10 -> a fresh identity holds 10 claims; each expiry costs 25 budget until the floor of 2"
  },
  "reputation_gained": {
   "reputation": 0.0,
   "deliverables_not_written": 1
  },
  "cost_per_point": 1.0,
  "detectability": "/v1/status vs the task list already shows hidden rows, and the bond ledger is public: an identity that bonds, claims bounties and expires them is a ledger read.",
  "mitigation": "Slash the BOND (already 1 USDC) but also make the budget penalty proportional to the bounty rather than flat 25, so a serial expirer of large bounties loses more budget per offence.",
  "honest_agent_side_effects": "Honest agents who abandon a bounty claim because the buyer went silent are already covered by the score-floor at 2; a proportional penalty would punish them harder for the same silence."
 }
]

